#pragma once
// Text is built into the app; the server controls only whether the notice is shown.
namespace securitynotice {
inline const wchar_t* title(){static const wchar_t* t[]={L"보안 검사 안내",L"Security scan notice",L"安全扫描通知",L"セキュリティ検査のお知らせ",L"Уведомление о проверке",L"Aviso de seguridad",L"Aviso de segurança",L"Hinweis zur Sicherheitsprüfung",L"Avis de sécurité",L"Avviso di sicurezza",L"Informacja o skanowaniu",L"Güvenlik taraması bildirimi",L"安全掃描通知"};return t[i18n::language.load()];}
inline const wchar_t* body(){static const wchar_t* t[]={L"안녕하세요, BlueAsh입니다. 2.29.0 설치 파일을 바이러스로 탐지한 백신이 4곳에서 3곳으로 줄었습니다. 나머지 업체에도 재검토를 요청했으며 결과가 확인되는 대로 안내드리겠습니다.",L"The BlueAsh 2.29.0 installer is now flagged as malicious by 3 security vendors, down from 4. We have requested reviews and will share further results.",L"将 BlueAsh 2.29.0 安装文件标记为恶意软件的厂商已从 4 家减少至 3 家。我们已申请复查，结果确认后将告知您。",L"BlueAsh 2.29.0 のインストーラーをマルウェアとして検出する製品は4社から3社に減りました。残る各社に再調査を依頼し、結果をお知らせします。",L"Число продуктов, считающих установщик BlueAsh 2.29.0 вредоносным, снизилось с 4 до 3. Мы запросили проверку и сообщим о результатах.",L"Los proveedores que detectan el instalador de BlueAsh 2.29.0 como malicioso han bajado de 4 a 3. Hemos solicitado revisiones y comunicaremos los resultados.",L"Os produtos que identificam o instalador do BlueAsh 2.29.0 como malicioso diminuíram de 4 para 3. Solicitamos revisões e informaremos os resultados.",L"Die Zahl der Produkte, die den BlueAsh-2.29.0-Installer als schädlich einstufen, sank von 4 auf 3. Wir haben Überprüfungen angefordert und informieren über die Ergebnisse.",L"Le nombre de produits signalant l’installateur BlueAsh 2.29.0 comme malveillant est passé de 4 à 3. Nous avons demandé des réexamens et communiquerons les résultats.",L"I prodotti che segnalano l’installer di BlueAsh 2.29.0 come dannoso sono passati da 4 a 3. Abbiamo richiesto verifiche e comunicheremo i risultati.",L"Liczba programów wykrywających instalator BlueAsh 2.29.0 jako złośliwy spadła z 4 do 3. Poprosiliśmy o analizę i poinformujemy o wynikach.",L"BlueAsh 2.29.0 yükleyicisini zararlı olarak işaretleyen ürün sayısı 4'ten 3'e düştü. İnceleme talep ettik; sonuçları paylaşacağız.",L"將 BlueAsh 2.29.0 安裝程式標記為惡意軟體的廠商已從 4 家減少至 3 家。我們已申請複查，結果確認後將通知您。"};return t[i18n::language.load()];}
inline const wchar_t* empty(){static const wchar_t* t[]={L"새로운 알림이 없습니다.",L"No new notifications.",L"暂无新通知。",L"新しいお知らせはありません。",L"Новых уведомлений нет.",L"No hay avisos nuevos.",L"Nenhum aviso novo.",L"Keine neuen Mitteilungen.",L"Aucune nouvelle notification.",L"Nessuna nuova notifica.",L"Brak nowych powiadomień.",L"Yeni bildirim yok.",L"目前沒有新通知。"};return t[i18n::language.load()];}
inline const wchar_t* link(){static const wchar_t* t[]={L"검사 결과 보기 ↗",L"View scan results ↗",L"查看扫描结果 ↗",L"検査結果を見る ↗",L"Результаты проверки ↗",L"Ver resultados ↗",L"Ver resultados ↗",L"Prüfergebnis ansehen ↗",L"Voir les résultats ↗",L"Vedi i risultati ↗",L"Zobacz wyniki ↗",L"Sonuçları görüntüle ↗",L"查看掃描結果 ↗"};return t[i18n::language.load()];}
inline std::wstring result(int count){if(count<0){static const wchar_t* unknown[]={L"2.29.0 설치 파일에 대한 백신 재검토를 요청했습니다. 최신 결과는 검사 결과 보기에서 확인해 주세요.",L"Reviews of the BlueAsh 2.29.0 installer have been requested. Please view the scan results for the latest status.",L"我们已申请复查 BlueAsh 2.29.0 安装文件。请查看扫描结果以了解最新状态。",L"BlueAsh 2.29.0 インストーラーの再調査を依頼しました。最新状況は検査結果をご覧ください。",L"Для установщика BlueAsh 2.29.0 запрошена проверка. Последний статус указан в результатах сканирования.",L"Hemos solicitado revisiones del instalador BlueAsh 2.29.0. Consulta los resultados para conocer el estado actual.",L"Solicitamos revisões do instalador BlueAsh 2.29.0. Consulte os resultados para saber o estado atual.",L"Für den BlueAsh-2.29.0-Installer wurden Überprüfungen angefordert. Den aktuellen Stand finden Sie im Prüfergebnis.",L"Des réexamens de l’installateur BlueAsh 2.29.0 ont été demandés. Consultez les résultats pour connaître le statut actuel.",L"Abbiamo richiesto verifiche dell’installer BlueAsh 2.29.0. Consulta i risultati per lo stato attuale.",L"Poprosiliśmy o analizę instalatora BlueAsh 2.29.0. Aktualny stan znajdziesz w wynikach skanowania.",L"BlueAsh 2.29.0 yükleyicisi için inceleme talep edildi. Güncel durum için tarama sonuçlarına bakın.",L"我們已申請複查 BlueAsh 2.29.0 安裝程式。請查看掃描結果以瞭解最新狀態。"};return unknown[i18n::language.load()];}static const wchar_t* progress[]={L"BlueAsh 2.29.0 설치 파일을 바이러스로 탐지하는 업체는 현재 {n}곳입니다. 재검토를 요청했으며 결과를 확인하는 대로 안내드리겠습니다.",L"{n} security vendors currently flag the BlueAsh 2.29.0 installer as malicious. Reviews have been requested; we will share the results.",L"目前有 {n} 家安全厂商将 BlueAsh 2.29.0 安装文件标记为恶意软件。我们已申请复查，并会公布结果。",L"現在、{n}社が BlueAsh 2.29.0 のインストーラーをマルウェアとして検出しています。再調査を依頼しており、結果をお知らせします。",L"Сейчас {n} защитных продуктов считают установщик BlueAsh 2.29.0 вредоносным. Мы запросили проверку и сообщим о результатах.",L"Actualmente {n} proveedores detectan el instalador de BlueAsh 2.29.0 como malicioso. Hemos solicitado revisiones e informaremos del resultado.",L"Atualmente, {n} produtos identificam o instalador do BlueAsh 2.29.0 como malicioso. Solicitamos revisões e informaremos os resultados.",L"Der BlueAsh-2.29.0-Installer wird derzeit von {n} Sicherheitsprodukten als schädlich eingestuft. Überprüfungen sind angefragt; wir informieren über die Ergebnisse.",L"L’installateur BlueAsh 2.29.0 est actuellement signalé comme malveillant par {n} produits. Nous avons demandé des réexamens et communiquerons les résultats.",L"Attualmente {n} prodotti segnalano l’installer di BlueAsh 2.29.0 come dannoso. Abbiamo richiesto verifiche e comunicheremo i risultati.",L"Obecnie {n} programów wykrywa instalator BlueAsh 2.29.0 jako złośliwy. Poprosiliśmy o analizę i poinformujemy o wynikach.",L"BlueAsh 2.29.0 yükleyicisini şu anda {n} güvenlik ürünü zararlı olarak işaretliyor. İnceleme talep ettik ve sonuçları paylaşacağız.",L"目前有 {n} 家安全廠商將 BlueAsh 2.29.0 安裝程式標記為惡意軟體。我們已申請複查，並會公布結果。"};static const wchar_t* clear[]={L"2.29.0 설치 파일을 탐지하던 4곳에 재검토를 요청한 후, VirusTotal 최신 검사에서 탐지가 0곳이 되었습니다. 다른 백신에서 탐지되면 버그 제보로 알려주시면 감사하겠습니다.",L"The latest VirusTotal scan found no detections for the 2.29.0 installer. If another security product flags it, please let us know via bug report.",L"VirusTotal 最新扫描中，2.29.0 安装文件的检测数已降至 0。如果其他安全软件仍有提示，请通过错误报告告知我们。",L"VirusTotal の最新検査では、2.29.0 インストーラーの検出数が0になりました。他の製品で検出された場合は不具合報告からお知らせください。",L"В последней проверке VirusTotal установщик 2.29.0 не обнаружен ни одним продуктом. Если другое защитное ПО выдаст предупреждение, сообщите об этом.",L"El último análisis de VirusTotal no detectó amenazas en el instalador 2.29.0. Si otro antivirus lo señala, avísanos mediante un informe de errores.",L"Na última análise do VirusTotal, o instalador 2.29.0 não teve detecções. Se outro antivírus o sinalizar, informe-nos pelo relatório de erros.",L"Beim letzten VirusTotal-Scan wurde der Installer 2.29.0 nicht erkannt. Falls ein anderes Sicherheitsprodukt ihn meldet, nutzen Sie bitte die Fehlerübermittlung.",L"La dernière analyse VirusTotal ne signale plus l’installateur 2.29.0. Si un autre antivirus le détecte, merci de nous le signaler.",L"L’ultima analisi VirusTotal non rileva l’installer 2.29.0. Se un altro antivirus lo segnala, avvisaci tramite la segnalazione di errori.",L"Ostatni skan VirusTotal nie wykrył instalatora 2.29.0. Jeśli inny program go wykryje, prosimy o zgłoszenie błędu.",L"Son VirusTotal taramasında 2.29.0 yükleyicisi için tespit kalmadı. Başka bir güvenlik ürünü uyarırsa lütfen hata bildirimiyle haber verin.",L"VirusTotal 最新掃描中，2.29.0 安裝程式的偵測數已降至 0。若其他安全軟體仍有提示，請透過錯誤回報告知我們。"};std::wstring s=(count==0?clear:progress)[i18n::language.load()];auto pos=s.find(L"{n}");if(pos!=std::wstring::npos)s.replace(pos,3,std::to_wstring(count));return s;}
}
